/**
 * After `next build`, copy the XML sitemaps and robots.txt generated by the
 * Laravel admin (SEO Settings > Sitemap) into out/, so the website serves:
 *
 *   /sitemap_index.xml  (+ /sitemap.xml, same content)
 *   /page-sitemap.xml, /post-sitemap.xml, /category-sitemap.xml (if enabled)
 *   /robots.txt
 *
 * Sitemap disabled in the admin (index returns 404) -> no sitemap files are
 * published. On CI (CI=true) any other failure fails the build, so stale SEO
 * files are never deployed; locally it only warns and keeps public/ copies.
 */
import { existsSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.join(__dirname, '..', 'out');

// ADMIN_API_URL is ".../api"; the sitemap routes live one level up.
const API = (process.env.ADMIN_API_URL || 'http://127.0.0.1:8000/api').replace(/\/+$/, '');
const ADMIN_BASE = API.replace(/\/api$/, '');

async function get(url) {
  const res = await fetch(url, { headers: { Accept: 'application/xml, text/plain' }, signal: AbortSignal.timeout(60000) });
  return { status: res.status, body: res.ok ? await res.text() : '' };
}

function write(file, body) {
  writeFileSync(path.join(OUT, file), body);
  console.log(`[seo] wrote out/${file} (${body.length} bytes)`);
}

function removeSitemaps() {
  for (const f of readdirSync(OUT)) {
    if (/^(.*-)?sitemap(_index)?\.xml$/.test(f)) {
      rmSync(path.join(OUT, f));
      console.log(`[seo] removed out/${f} (sitemap disabled in admin)`);
    }
  }
}

async function main() {
  if (!existsSync(OUT)) throw new Error('out/ not found - run next build first');

  // robots.txt (via the API route: the admin's own public/robots.txt file
  // shadows its /robots.txt route)
  const robots = await get(`${API}/seo/robots.txt`);
  if (robots.status !== 200 || !robots.body.trim()) throw new Error(`robots.txt: HTTP ${robots.status}`);
  write('robots.txt', robots.body);

  // sitemap index
  const index = await get(`${ADMIN_BASE}/sitemap_index.xml`);
  if (index.status === 404) {
    removeSitemaps();
    return;
  }
  if (index.status !== 200 || !index.body.includes('<sitemapindex')) throw new Error(`sitemap_index.xml: HTTP ${index.status}`);

  removeSitemaps(); // drop the old hand-made public/sitemap.xml copy and any stale children
  write('sitemap_index.xml', index.body);
  write('sitemap.xml', index.body);

  const children = [...index.body.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => path.posix.basename(new URL(m[1]).pathname));
  for (const file of children) {
    const child = await get(`${ADMIN_BASE}/${file}`);
    if (child.status !== 200 || !child.body.includes('<urlset')) throw new Error(`${file}: HTTP ${child.status}`);
    write(file, child.body);
  }
}

main().catch((err) => {
  if (process.env.CI) {
    console.error(`[seo] failed: ${err.message}`);
    process.exit(1);
  }
  console.warn(`[seo] skipped (${err.message}); keeping the sitemap/robots files from public/`);
});
